package parse_test

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/toncenter/ton-indexer/ton-index-go/index/parse"
)

// TestFrozenPayloadBytes decodes the frozen payload byte set of the compact codec transition
// and requires the frozen API JSON byte for byte.
//
// `testdata/payload_frozen_v1.jsonl.gz` was created ONCE when codec byte 1 changed in place
// from the wrapped name-keyed body (`01` + `{data: {...}}`) to the compact id-keyed map. It is
// NOT regenerated by ordinary baseline regeneration, which writes only
// `payload_contract.jsonl.gz` and `payload_contract.metadata.json`. Change this
// file only with the owner's decision, together with the pinned sha256 below.
//
// Each row carries fixture_id, action_id, type, payload_hex, wire_hex and the frozen `api`
// (the wire column is the envelope carrier, which the payload alone cannot reproduce). The
// payload bytes are decoded by the current decoder, so renumbering or retyping an existing
// registry key - or reformatting these bytes - fails here.
const (
	frozenPayloadPath   = "testdata/payload_frozen_v1.jsonl.gz"
	frozenPayloadSHA256 = "7a044f92239c4fdfe9d5edf07680335e7a02cd485dcf0f143387e8489d9208df"
	frozenPayloadRows   = 1220
)

func TestFrozenPayloadBytes(t *testing.T) {
	blob, err := os.ReadFile(frozenPayloadPath)
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(blob)
	if got := hex.EncodeToString(digest[:]); got != frozenPayloadSHA256 {
		t.Fatalf("frozen set sha256 = %s, want %s (created once at the codec transition, edit only with the owner's decision)", got, frozenPayloadSHA256)
	}
	z, err := gzip.NewReader(bytes.NewReader(blob))
	if err != nil {
		t.Fatal(err)
	}
	defer z.Close()

	count := 0
	s := bufio.NewScanner(z)
	s.Buffer(nil, 16<<20)
	for s.Scan() {
		var row payloadContractRow
		if err := json.Unmarshal(s.Bytes(), &row); err != nil {
			t.Fatalf("row %d: %v", count+1, err)
		}
		count++
		key := row.FixtureID + "/" + row.ActionID + "/" + row.Type
		t.Run(key, func(t *testing.T) {
			if len(row.API) == 0 {
				t.Fatal("missing API JSON")
			}
			// The frozen wire and the frozen payload column must agree.
			assertWirePayload(t, row.Wire, row.Payload)
			raw := *decodeWireAction(t, row.Wire)
			clearPayloadFields(&raw)
			payload, err := hex.DecodeString(row.Payload)
			if err != nil {
				t.Fatal(err)
			}
			if err := parse.DecodeActionPayload(payload, &raw); err != nil {
				t.Fatal(err)
			}
			action, err := parse.ParseRawAction(&raw)
			if err != nil {
				t.Fatal(err)
			}
			got, err := json.Marshal(action)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, row.API) {
				t.Errorf("frozen payload decodes to a different API\nwant: %s\ngot:  %s", row.API, got)
			}
		})
	}
	if err := s.Err(); err != nil {
		t.Fatal(err)
	}
	if count != frozenPayloadRows {
		t.Fatalf("frozen set has %d rows, want %d", count, frozenPayloadRows)
	}
}
